var CONTINUT_TOPOLOGIE={};
CONTINUT_TOPOLOGIE["teorema-heine-borel"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> O submulțime a lui ℝⁿ este compactă dacă și numai dacă este închisă și mărginită.</div>",formula_display:"Compact în ℝⁿ ↔ închis și mărginit",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"80\" y=\"18\" font-size=\"12\" fill=\"#1a6040\" text-anchor=\"middle\">compact = cutie cu capac</text><rect x=\"20\" y=\"28\" width=\"120\" height=\"110\" rx=\"10\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"3\"/><circle cx=\"80\" cy=\"83\" r=\"38\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"3\"/><text x=\"80\" y=\"160\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">închis + mărginit</text><text x=\"240\" y=\"18\" font-size=\"12\" fill=\"#c8922a\" text-anchor=\"middle\">necompact = fără capac</text><rect x=\"180\" y=\"28\" width=\"120\" height=\"110\" rx=\"10\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3\" stroke-dasharray=\"8 5\"/><line x1=\"192\" y1=\"83\" x2=\"288\" y2=\"83\" stroke=\"#c8922a\" stroke-width=\"4\" stroke-dasharray=\"3 4\"/><text x=\"240\" y=\"160\" font-size=\"11\" fill=\"#c8922a\" text-anchor=\"middle\">\"scapă\" spre margine</text></svg>",intuitiv_text:"<span class=\"hl\">O mulțime compactă e ca o cutie de jucării cu capac bine închis - nimic nu lipsește de la margine și nimic nu poate scăpa spre infinit</span>. O cutie fără capac (îi lipsește marginea) sau fără fund (nu are limită) nu mai e „compactă”.",intuitiv_nota:"Rezultatul poartă numele lui Heine, care l-a schițat în 1872, și al lui Borel, care i-a dat forma generală în 1895. Astăzi e un instrument esențial în analiza funcțională și în teoria optimizării.",exercitii:[{"q":"Este intervalul [0,1] o mulțime compactă în ℝ?","pasi":["Intervalul conține ambele capete 0 și 1, deci este închis.","Este conținut, de exemplu, între -1 și 2, deci este mărginit.","Fiind închis și mărginit, prin Heine-Borel este compact."],"r":"✓ <strong>Da</strong>, [0,1] e compact"},{"q":"De ce (0,1) NU este compact, deși e mărginit?","pasi":["Șirul xₙ=1/n este în (0,1) și converge la 0, care nu aparține mulțimii.","Deci (0,1) nu conține toate limitele posibile ale șirurilor din el - nu e închis.","Fiindu-i „capacul” lipsă (capetele 0 și 1), (0,1) nu e compact, deși e mărginit."],"r":"✓ <strong>Nu</strong> - lipsește închiderea"},{"q":"O mulțime finită, de exemplu {1,2,3}⊂ℝ, este compactă?","pasi":["O mulțime finită e automat mărginită, are un număr finit de puncte.","E automat și închisă, pentru că nu are puncte de acumulare în afara ei.","Fiind închisă și mărginită, {1,2,3} este compactă - cel mai simplu exemplu posibil."],"r":"✓ <strong>Da</strong>, orice mulțime finită e compactă"},{"q":"Adevărat sau fals: „orice mulțime mărginită este compactă”?","pasi":["Fals - mărginirea singură nu e suficientă, mai trebuie și închiderea.","Contraexemplu: (0,1) e mărginit, dar nu e închis, deci nu e compact.","Ambele condiții, închis ȘI mărginit, sunt necesare simultan."],"r":"✓ <strong>Fals</strong> - mai trebuie și „închis”"},{"q":"De ce garantăm că o funcție continuă are un maxim pe [a,b], dar nu neapărat pe (a,b)?","pasi":["[a,b] este compact, închis și mărginit, deci teorema Weierstrass garantează atingerea maximului și minimului.","(a,b) nu e închis - funcția poate „urca” tot mai aproape de capăt fără să atingă vreodată maximul acolo.","Exemplu: f(x)=x pe (0,1) nu are maxim - se apropie de 1 dar nu-l atinge niciodată."],"r":"✓ Compacitatea garantează atingerea extremelor (<strong>Weierstrass</strong>)"}]};
CONTINUT_TOPOLOGIE["teorema-punctului-fix-brouwer"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice funcție continuă f:Dⁿ→Dⁿ de la discul n-dimensional la el însuși are cel puțin un punct fix x cu f(x)=x.</div>",formula_display:"f:Dⁿ→Dⁿ continuă → ∃x: f(x)=x",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"150\" cy=\"90\" r=\"70\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"3\"/><path d=\"M150 30 A60 60 0 0 1 210 90\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\" marker-end=\"url(#a1)\"/><path d=\"M210 90 A60 60 0 0 1 150 150\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\" marker-end=\"url(#a1)\"/><path d=\"M150 150 A60 60 0 0 1 90 90\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\" marker-end=\"url(#a1)\"/><path d=\"M90 90 A60 60 0 0 1 150 30\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\" marker-end=\"url(#a1)\"/><defs><marker id=\"a1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0 0L8 4L0 8Z\" fill=\"#1a6040\"/></marker></defs><circle cx=\"150\" cy=\"90\" r=\"6\" fill=\"#c8922a\"/><text x=\"150\" y=\"170\" font-size=\"12\" fill=\"#c8922a\" text-anchor=\"middle\">punctul care nu se mișcă</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă amesteci laptele din cana ta, oricât de mult amesteci, există mereu un strop care rămâne exact în locul lui de la început</span>. Asta e valabil doar dacă amesteci înăuntrul cănii (un disc plin), nu pe marginea unui inel.",intuitiv_nota:"Luitzen Brouwer a demonstrat teorema în 1910, folosind instrumente de topologie algebrică. Ideea s-a dovedit surprinzător de fertilă: apare în teoria jocurilor, la echilibrul Nash, în economia matematică și în teoria ecuațiilor diferențiale.",exercitii:[{"q":"Funcția f:[-1,1]→[-1,1], f(x)=x/3+1/3 este continuă. Găsiți punctul ei fix.","pasi":["Căutăm x* cu f(x*)=x*, adică x*/3+1/3=x*.","Rezolvăm: 1/3=x*-x*/3=2x*/3, deci x*=1/2.","Verificăm: f(1/2)=1/6+1/3=1/2 ✔ - punctul fix există și e unic aici."],"r":"✓ x*=<strong>1/2</strong>"},{"q":"Rotația f:S¹→S¹ cu unghi π (f(x)=-x) nu are punct fix. Contrazice asta teorema lui Brouwer?","pasi":["Brouwer se aplică discului plin Dⁿ, inclusiv interiorul, nu cercului S¹ care e doar „coaja”.","Cercul S¹ nu e homeomorf cu discul D² - îi lipsește interiorul, deci ipoteza teoremei nu e satisfăcută.","Nu există contradicție: pe cerc pot exista funcții continue fără punct fix."],"r":"✓ <strong>Nu contrazice</strong> - Brouwer nu se aplică pe S¹"},{"q":"Funcția identitate f(x)=x pe D². Care sunt punctele ei fixe?","pasi":["f(x)=x înseamnă că orice punct x satisface automat f(x)=x.","Deci toate punctele discului sunt puncte fixe simultan - cazul extrem, opus unui punct fix unic.","Este cel mai simplu exemplu posibil pentru teoremă, deși nu foarte informativ."],"r":"✓ <strong>Toate punctele</strong> discului sunt fixe"},{"q":"Adevărat sau fals: dacă f:D²→ℝ² e continuă dar imaginea ei poate ieși din D², Brouwer garantează tot un punct fix?","pasi":["Fals - ipoteza esențială este ca f să trimită discul ÎN el însuși (f:D²→D²).","Dacă f(x) poate „ieși” din disc, nu mai există garanția din demonstrație.","Exemplu: f(x)=2x pe D² trimite punctele în afara discului, pentru x≠0, și nu are punct fix în D² în afară de origine, care oricum nu se mișcă."],"r":"✓ <strong>Fals</strong> - trebuie ca f să rămână în D²"},{"q":"O hartă mototolită (dar nu ruptă) și pusă înapoi peste harta originală întinsă pe masă. Există un punct exact deasupra locului lui de pe original?","pasi":["Punerea hărții mototolite peste original definește o funcție continuă de la regiunea mesei la ea însăși.","Regiunea mesei acoperită de hartă e homeomorfă cu un disc.","Prin Brouwer, există garantat un punct al hărții exact deasupra punctului corespunzător de pe masă."],"r":"✓ <strong>Da</strong> - e aplicația clasică a teoremei lui Brouwer"}]};
CONTINUT_TOPOLOGIE["teorema-lui-jordan"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice curbă Jordan (simplă, închisă, continuă) din planul ℝ² împarte planul în exact două componente conexe: un interior mărginit și un exterior nemărginit.</div>",formula_display:"Curbă Jordan → ℝ²\\ Γ = Interior ∪ Exterior",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M150 30 C210 30 230 70 220 100 C210 140 170 150 130 140 C90 130 70 90 90 60 C100 40 120 30 150 30 Z\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"3\"/><circle cx=\"150\" cy=\"90\" r=\"5\" fill=\"#c8922a\"/><text x=\"150\" y=\"113\" font-size=\"11\" fill=\"#c8922a\" text-anchor=\"middle\">interior</text><circle cx=\"270\" cy=\"30\" r=\"5\" fill=\"#1a6040\"/><text x=\"270\" y=\"48\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">exterior</text></svg>",intuitiv_text:"<span class=\"hl\">O sfoară așezată pe masă, cu capetele legate între ele fără să se încrucișeze, împarte mereu masa în două: înăuntrul sforii și afara ei</span>. Nu poți trece de la interior la exterior fără să calci pe sfoară.",intuitiv_nota:"Camille Jordan (1887) a enunțat teorema; demonstrația riguroasă a venit abia cu Veblen (1905). Este non-trivială din cauza curbelor patologice.",exercitii:[{"q":"Un cerc C în plan. În câte regiuni împarte planul, conform teoremei lui Jordan?","pasi":["Cercul este o curbă simplă, care nu se auto-intersectează, și închisă, deci e o curbă Jordan.","Teorema garantează exact două componente conexe: interiorul (discul) și exteriorul (restul planului).","Orice punct din plan e fie strict înăuntrul cercului, fie strict în afara lui, niciodată „pe ambele”."],"r":"✓ <strong>2 regiuni</strong>: interior și exterior"},{"q":"Figura 8 (∞), care se auto-intersectează într-un punct. Este curbă Jordan? Câte regiuni delimitează?","pasi":["Nu este curbă Jordan, pentru că se auto-intersectează în punctul central - condiția de „simplă” nu e îndeplinită.","Teorema lui Jordan nu se aplică direct aici.","De fapt, figura 8 împarte planul în 3 regiuni (cele două bucle plus exteriorul), nu în 2 ca o curbă Jordan."],"r":"✓ <strong>Nu e Jordan</strong> - dă 3 regiuni, nu 2"},{"q":"O elipsă foarte turtită, aproape ca un segment de dreaptă. Mai are interior și exterior distincte?","pasi":["Oricât de turtită, elipsa rămâne o curbă simplă și închisă, deci tot o curbă Jordan.","Interiorul devine o fâșie foarte subțire, dar tot există ca regiune separată de exterior.","Cele 2 componente rămân garantate de teoremă indiferent de cât de „subțire” arată interiorul."],"r":"✓ <strong>Da</strong>, tot 2 regiuni, chiar dacă interiorul e foarte îngust"},{"q":"Adevărat sau fals: orice curbă închisă simplă din plan împarte planul în exact 3 regiuni.","pasi":["Fals - teorema lui Jordan garantează exact 2 regiuni: interior și exterior, nu 3.","Confuzia poate veni de la curbe care se auto-intersectează, ca figura 8, care NU sunt curbe Jordan și pot da mai multe regiuni.","Pentru orice curbă Jordan adevărată, răspunsul corect e mereu 2."],"r":"✓ <strong>Fals</strong> - sunt exact 2 regiuni"},{"q":"Un gard închis, fără porți, în jurul unei curți. Poate un câine din curte să ajungă în stradă fără să sară gardul?","pasi":["Gardul închis, fără auto-intersecții, formează o curbă Jordan în planul curții.","Teorema garantează că interiorul (curtea) și exteriorul (strada) sunt regiuni complet separate.","Câinele nu poate trece continuu de la interior la exterior fără să traverseze gardul."],"r":"✓ <strong>Nu</strong>, fără să treacă prin gard"}]};
CONTINUT_TOPOLOGIE["teorema-borsuk-ulam"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pentru orice funcție continuă f:Sⁿ→ℝⁿ de la sfera n-dimensională în ℝⁿ, există un punct x cu f(x)=f(-x) (puncte antipodale cu aceleași valori).</div>",formula_display:"∀f:Sⁿ→ℝⁿ continuă: ∃x∈Sⁿ cu f(x)=f(-x)",diagrama:"<svg viewBox=\"0 0 300 190\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"110\" cy=\"95\" r=\"70\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"3\"/><line x1=\"60\" y1=\"55\" x2=\"160\" y2=\"135\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"5 4\"/><circle cx=\"60\" cy=\"55\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"160\" cy=\"135\" r=\"6\" fill=\"#c8922a\"/><text x=\"110\" y=\"180\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">puncte antipodale pe sferă</text><rect x=\"230\" y=\"40\" width=\"30\" height=\"110\" rx=\"6\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\"/><line x1=\"230\" y1=\"95\" x2=\"260\" y2=\"95\" stroke=\"#c8922a\" stroke-width=\"3\"/><text x=\"245\" y=\"30\" font-size=\"10\" fill=\"#1a6040\" text-anchor=\"middle\">aceeași valoare</text></svg>",intuitiv_text:"<span class=\"hl\">Pe glob există mereu două puncte exact opuse (antipodale) cu aceeași temperatură în același moment</span>. Oriunde ai roti globul, undeva cele două „capete” opuse se potrivesc mereu.",intuitiv_nota:"Borsuk și Ulam au publicat rezultatul în 1933, cu o demonstrație bazată pe omologie. Din el decurge teorema ham sandwich, care spune că orice n mulțimi pot fi bisectate simultan de un hiperplan.",exercitii:[{"q":"f:S¹→ℝ dată de f(x,y)=x (proiecția pe axa Ox) pe cercul unitate. Găsiți punctele antipodale cu aceeași valoare.","pasi":["Căutăm (x,y) pe cerc cu f(x,y)=f(-x,-y), adică x=-x.","Din x=-x rezultă x=0.","Pe cerc, x=0 dă punctele (0,1) și (0,-1) - exact perechea antipodală căutată."],"r":"✓ punctele <strong>(0,1) și (0,-1)</strong>"},{"q":"De ce nu e „interesant” exemplul f(x,y)=x²+y² pe S¹ pentru teoremă?","pasi":["Pe cercul unitate, x²+y²=1 pentru toate punctele - funcția e constantă.","O funcție constantă satisface trivial f(x)=f(-x) pentru orice pereche de puncte, nu doar pentru una specială.","Exemplul nu ilustrează forța teoremei, care garantează o pereche specifică chiar și pentru funcții neconstante."],"r":"✓ Exemplu <strong>trivial</strong> - nu ilustrează teorema"},{"q":"Cazul cel mai simplu: f:S⁰→ℝ, unde S⁰={-1,1}. Ce spune teorema aici?","pasi":["S⁰ are doar două puncte, -1 și 1, care sunt deja antipodale.","Teorema ar cere ∃x cu f(x)=f(-x), adică f(-1)=f(1), lucru ce NU e adevărat pentru orice f.","Enunțul standard al Borsuk-Ulam cere n≥1; cazul n=0 arată de ce dimensiunea contează în ipoteze."],"r":"✓ Cazul degenerat arată <strong>de ce e nevoie de n≥1</strong>"},{"q":"Adevărat sau fals: teorema Borsuk-Ulam se aplică oricărei funcții continue f:Sⁿ→ℝᵐ, indiferent de m.","pasi":["Fals - enunțul cere ca dimensiunea codomeniului să fie exact n (f:Sⁿ→ℝⁿ), nu mai mare.","Dacă m&gt;n, în general nu mai există garanția unei perechi antipodale cu aceeași valoare.","Dimensiunea codomeniului trebuie să fie „la fel de mică” precum a domeniului minus 1."],"r":"✓ <strong>Fals</strong> - trebuie codomeniu de dimensiune exact n"},{"q":"Teorema ham sandwich: un sandviș cu pâine, șuncă și brânză poate fi tăiat cu o singură tăietură plană astfel încât fiecare ingredient să fie împărțit exact în jumătate?","pasi":["Fiecare ingredient e o mulțime în spațiul 3D, iar căutăm un plan care bisectează simultan toate cele 3.","Aceasta e o consecință directă a teoremei Borsuk-Ulam aplicată pe S³.","Răspunsul e garantat afirmativ - de aici și numele „teorema sandvișului cu șuncă”."],"r":"✓ <strong>Da</strong>, întotdeauna există o astfel de tăietură"}]};
CONTINUT_TOPOLOGIE["caracteristica-euler-topologie"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Caracteristica Euler χ=V-E+F (vârfuri minus muchii plus fețe) este invariant topologic: pentru orice triangulaţie a suprafeței, χ ia aceeași valoare.</div>",formula_display:"χ = V − E + F (invariant topologic)",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"90\" cy=\"85\" r=\"55\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"3\"/><line x1=\"90\" y1=\"30\" x2=\"90\" y2=\"140\" stroke=\"#1a6040\" stroke-width=\"1.5\"/><line x1=\"35\" y1=\"85\" x2=\"145\" y2=\"85\" stroke=\"#1a6040\" stroke-width=\"1.5\"/><line x1=\"53\" y1=\"47\" x2=\"127\" y2=\"123\" stroke=\"#1a6040\" stroke-width=\"1.5\"/><text x=\"90\" y=\"165\" font-size=\"13\" fill=\"#1a6040\" text-anchor=\"middle\">sferă: χ=2</text><ellipse cx=\"220\" cy=\"85\" rx=\"65\" ry=\"42\" fill=\"#c8922a22\" stroke=\"#c8922a\" stroke-width=\"3\"/><ellipse cx=\"220\" cy=\"85\" rx=\"24\" ry=\"15\" fill=\"#ffffff\" stroke=\"#c8922a\" stroke-width=\"3\"/><text x=\"220\" y=\"165\" font-size=\"13\" fill=\"#c8922a\" text-anchor=\"middle\">tor (gaură): χ=0</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă desenezi linii pe o minge de fotbal ca să o împarți în bucăți - colțuri, muchii, fețe - numărul colțuri minus muchii plus fețe iese mereu 2, oricum ai desenat liniile</span>. Pe un covrig cu gaură, același calcul dă mereu 0.",intuitiv_nota:"Euler a introdus formula în 1752 pentru poliedre, iar Poincaré a generalizat-o ulterior la suprafețe oarecare. Astăzi χ, alături de orientabilitate, stă la baza clasificării suprafețelor compacte.",exercitii:[{"q":"Un cub: V=8 vârfuri, E=12 muchii, F=6 fețe. Calculați χ.","pasi":["Aplicăm formula χ=V-E+F.","χ=8-12+6=2.","Rezultatul e 2, la fel ca pentru sferă - cubul e topologic „aceeași formă” ca sfera, poate fi umflat rotund."],"r":"✓ χ=<strong>2</strong>"},{"q":"O suprafață are χ=-2. Câte „găuri” (gen g) are, știind formula χ=2-2g?","pasi":["Punem χ=2-2g=-2.","Rezolvăm: 2g=2-(-2)=4, deci g=2.","Suprafața are 2 găuri - ca un pretzel cu două inele lipite."],"r":"✓ g=<strong>2 găuri</strong>"},{"q":"Un disc plin, triangulat cu margine (nu o suprafață închisă), cu V=4,E=4,F=1. Calculați χ. E la fel ca pentru sferă?","pasi":["χ=4-4+1=1.","Discul, care are o margine, are χ=1, diferit de sfera închisă unde χ=2.","Cazul cu margine e special - formula tot se aplică, dar valoarea diferă de suprafețele fără margine."],"r":"✓ χ=<strong>1</strong> (diferit de sferă, are margine)"},{"q":"Adevărat sau fals: dacă triangulăm aceeași sferă în două moduri diferite, cu mai multe sau mai puține triunghiuri, obținem valori diferite ale lui χ.","pasi":["Fals - χ este un invariant topologic, nu depinde de modul în care triangulăm suprafața.","Oricâte muchii sau fețe am adăuga, respectând regulile triangulației, V-E+F rămâne același.","Aceasta e chiar ideea centrală a teoremei: χ „vede” doar forma de bază, nu detaliile desenului."],"r":"✓ <strong>Fals</strong> - χ nu depinde de triangulație"},{"q":"O minge de fotbal are 12 pentagoane și 20 hexagoane, cu V=60, E=90, F=32. Calculați χ și verificați dacă e „topologic o sferă”.","pasi":["χ=60-90+32=2.","χ=2 corespunde exact sferei, genus 0, fără găuri.","Confirmă intuiția: mingea de fotbal, deși are colțuri și fețe plate, e topologic echivalentă cu o sferă rotundă."],"r":"✓ χ=<strong>2</strong> - topologic o sferă"}]};
CONTINUT_TOPOLOGIE["conjectura-lui-poincare-perelman"]={definitie:"<div class=\"def-box\"><strong>Enunț (demonstrat):</strong> Orice 3-varietate compactă, fără margine, simplu conexă este homeomorfă cu sfera S³.</div>",formula_display:"M³ compactă, simplu conexă → M³ ≅ S³",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M60 60 C80 40 110 45 115 65 C125 55 140 70 130 90 C140 105 120 125 100 120 C85 135 55 125 55 105 C40 100 40 75 60 60 Z\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"3\"/><path d=\"M155 90 L185 90\" stroke=\"#1a6040\" stroke-width=\"2\" marker-end=\"url(#a2)\"/><defs><marker id=\"a2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0 0L8 4L0 8Z\" fill=\"#1a6040\"/></marker></defs><circle cx=\"225\" cy=\"90\" r=\"40\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"3\"/><text x=\"150\" y=\"20\" font-size=\"12\" fill=\"#1a6040\" text-anchor=\"middle\">fără gaură → devine sferă</text><ellipse cx=\"75\" cy=\"150\" rx=\"45\" ry=\"24\" fill=\"#c8922a22\" stroke=\"#c8922a\" stroke-width=\"3\"/><ellipse cx=\"75\" cy=\"150\" rx=\"16\" ry=\"9\" fill=\"#ffffff\" stroke=\"#c8922a\" stroke-width=\"3\"/><text x=\"150\" y=\"155\" font-size=\"20\" fill=\"#c8922a\" text-anchor=\"middle\">✕</text><text x=\"150\" y=\"178\" font-size=\"11\" fill=\"#c8922a\" text-anchor=\"middle\">cu gaură → nu devine sferă</text></svg>",intuitiv_text:"<span class=\"hl\">O minge de plastilină fără nicio gaură poate fi mereu frământată până devine o sferă perfect rotundă</span>. Un covrig cu gaură, oricât ai frământa, nu poate deveni vreodată o sferă fără să rupi plastilina.",intuitiv_nota:"Grigori Perelman a demonstrat în 2003 și a refuzat atât Medalia Fields (2006) cât și premiul de 1 milion USD. Una din cele mai mari realizări matematice recente.",exercitii:[{"q":"Sfera S² (suprafața unei mingi obișnuite) este simplu conexă?","pasi":["O mulțime e simplu conexă dacă orice buclă desenată pe ea poate fi „strânsă” continuu până la un punct, fără să iasă din suprafață.","Pe S², orice buclă desenată, de exemplu un lasou, poate fi trasă și strânsă spre un punct, alunecând liber pe suprafață.","Deci S² este simplu conexă."],"r":"✓ <strong>Da</strong>"},{"q":"Torul T² (suprafața unui covrig) este simplu conex?","pasi":["O buclă care înconjoară „gaura” covrigului nu poate fi strânsă la un punct fără să părăsească suprafața.","Această buclă rămâne „prinsă” în jurul găurii, oricât am deforma-o continuu pe suprafață.","Deci T² NU este simplu conex - exact acest tip de „gaură” e exclus de ipoteza conjecturii lui Poincaré."],"r":"✓ <strong>Nu</strong> - bucla din jurul găurii nu se contractă"},{"q":"Care e analogul conjecturii în dimensiune 2 și era el deja cunoscut înainte de Poincaré?","pasi":["În dimensiune 2, enunțul analog spune: orice suprafață compactă, simplu conexă, e homeomorfă cu S².","Acest rezultat era cunoscut încă din secolul XIX, din clasificarea completă a suprafețelor 2D compacte, prin genus.","Dificultatea reală a apărut abia în dimensiune 3, unde metodele clasificării 2D nu mai funcționau."],"r":"✓ <strong>Da</strong>, cazul 2D era deja rezolvat"},{"q":"Adevărat sau fals: orice 3-varietate compactă, fără altă condiție, este homeomorfă cu S³.","pasi":["Fals - conjectura cere explicit ca varietatea să fie și simplu conexă, nu doar compactă.","Există 3-varietăți compacte care NU sunt simplu conexe, au „găuri” de tip buclă necontractibilă, și care nu sunt homeomorfe cu S³.","Ambele ipoteze, compactitate ȘI simplă conexitate, sunt esențiale."],"r":"✓ <strong>Fals</strong> - lipsește condiția „simplu conexă”"},{"q":"De ce dimensiunea 3 a fost cea mai grea de demonstrat, deși dimensiunile mai mari s-au rezolvat mai devreme?","pasi":["Dimensiunile 1 și 2 erau ușoare, rezolvate demult prin clasificare directă.","Dimensiunile mari, ≥5, au fost rezolvate de Smale (1961), iar dimensiunea 4 de Freedman (1982), folosind spațiu „suficient” pentru manevre topologice.","Dimensiunea 3 nu are nici simplitatea celor mici, nici spațiul de manevră al celor mari - de aceea a rezistat până la Perelman (2003), care a folosit fluxul Ricci."],"r":"✓ Dimensiunea 3 era <strong>„prea strânsă”</strong> pentru metodele vechi"}]};
CONTINUT_TOPOLOGIE["lema-lui-zorn"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă fiecare lanț (submulțime total ordonată) dintr-un poset are o margine superioară în acel poset, atunci posetul are un element maximal.</div>",formula_display:"∀ lanț C: ∃margine superioară → ∃element maximal",diagrama:"<svg viewBox=\"0 0 260 200\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"90\" y=\"150\" width=\"80\" height=\"30\" rx=\"6\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"2\"/><rect x=\"75\" y=\"110\" width=\"110\" height=\"30\" rx=\"6\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"2\"/><rect x=\"60\" y=\"70\" width=\"140\" height=\"30\" rx=\"6\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"2\"/><rect x=\"45\" y=\"25\" width=\"170\" height=\"30\" rx=\"6\" fill=\"#c8922a22\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"130\" y1=\"150\" x2=\"130\" y2=\"140\" stroke=\"#1a6040\" stroke-width=\"1.5\"/><line x1=\"130\" y1=\"110\" x2=\"130\" y2=\"100\" stroke=\"#1a6040\" stroke-width=\"1.5\"/><line x1=\"130\" y1=\"70\" x2=\"130\" y2=\"55\" stroke=\"#1a6040\" stroke-width=\"1.5\"/><text x=\"130\" y=\"170\" font-size=\"10\" fill=\"#1a6040\" text-anchor=\"middle\">lanț crescător</text><text x=\"130\" y=\"43\" font-size=\"11\" fill=\"#c8922a\" text-anchor=\"middle\">element maximal</text></svg>",intuitiv_text:"<span class=\"hl\">Imaginează-ți o scară de cutii, fiecare cutie conținând-o pe cea de dinainte - dacă poți mereu găsi o cutie suficient de mare cât să le cuprindă pe toate cele de până atunci, atunci undeva există o cutie „cea mai mare”, care nu mai încape în nicio alta</span>.",intuitiv_nota:"Max Zorn a formulat lema în 1935; se dovedește echivalentă cu Axioma Alegerii și cu Teorema Bine-Ordonării. E folosită, printre altele, ca să se arate că orice spațiu vectorial are o bază sau că orice inel are un ideal maximal.",exercitii:[{"q":"În mulțimea submulțimilor proprii ale {1,2,3}, ordonată prin incluziune ⊆, care sunt elementele maximale?","pasi":["Element maximal înseamnă o submulțime care nu e strict conținută în nicio altă submulțime proprie din listă.","{1,2}, {1,3} și {2,3} nu sunt conținute în nicio altă submulțime proprie, pasul următor ar fi {1,2,3}, care e exclusă.","Există trei elemente maximale, nu unul singur - lema garantează EXISTENȚA a cel puțin unuia, nu unicitatea."],"r":"✓ <strong>{1,2}, {1,3}, {2,3}</strong> sunt maximale"},{"q":"De ce (ℕ,≤), numerele naturale cu ordinea uzuală, NU are element maximal, deși pare un poset simplu?","pasi":["Pentru orice n∈ℕ, există întotdeauna n+1&gt;n, deci niciun număr natural nu e „cel mai mare”.","Lanțul întreg ℕ nu are o margine superioară ÎN ℕ, deși are margini superioare în mulțimi mai mari, ca ℝ.","Aceasta arată de ce ipoteza „orice lanț are margine superioară în poset” din lema lui Zorn e esențială - aici ea eșuează, deci lema nu garantează nimic."],"r":"✓ <strong>Nu are</strong> - lanțul ℕ nu are margine superioară în ℕ"},{"q":"Cel mai simplu poset posibil: o mulțime cu un singur element, {a}. Are element maximal?","pasi":["Cu un singur element, relația de ordine e trivială: a≤a.","Elementul a nu poate fi depășit de niciun altul, nu mai există altele.","a este automat elementul maximal - cazul degenerat, dar confirmă că definiția funcționează și la limită."],"r":"✓ <strong>Da</strong>, a este maximal (trivial)"},{"q":"Adevărat sau fals: lema lui Zorn este echivalentă cu Axioma Alegerii.","pasi":["Adevărat - în cadrul axiomatic ZF (Zermelo-Fraenkel), lema lui Zorn, Axioma Alegerii și Teorema Bine-Ordonării se demonstrează una din cealaltă.","Asta înseamnă că acceptarea uneia dintre ele echivalează cu acceptarea celorlalte două.","Multe demonstrații de existență, bază pentru orice spațiu vectorial, ideal maximal în orice inel, folosesc Zorn tocmai pentru că e mai ușor de aplicat direct."],"r":"✓ <strong>Adevărat</strong>"},{"q":"Cum se folosește lema lui Zorn pentru a arăta că orice spațiu vectorial are o bază?","pasi":["Se ia posetul tuturor submulțimilor liniar independente din spațiu, ordonat prin incluziune ⊆.","Orice lanț de mulțimi liniar independente are o margine superioară: reuniunea lor, care rămâne liniar independentă.","Lema lui Zorn garantează un element maximal - o mulțime liniar independentă maximă, care este exact o bază a spațiului."],"r":"✓ Elementul maximal = <strong>o bază a spațiului</strong>"}]};
CONTINUT_TOPOLOGIE["teorema-tychonoff"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Produsul arbitrar (posibil infinit necontabil) de spații topologice compacte este compact în topologia produs.</div>",formula_display:"∏_α Xα compact dacă fiecare Xα compact",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"100\" height=\"100\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"3\"/><line x1=\"30\" y1=\"53\" x2=\"130\" y2=\"53\" stroke=\"#1a604066\" stroke-width=\"1\"/><line x1=\"30\" y1=\"86\" x2=\"130\" y2=\"86\" stroke=\"#1a604066\" stroke-width=\"1\"/><line x1=\"63\" y1=\"20\" x2=\"63\" y2=\"120\" stroke=\"#1a604066\" stroke-width=\"1\"/><line x1=\"96\" y1=\"20\" x2=\"96\" y2=\"120\" stroke=\"#1a604066\" stroke-width=\"1\"/><text x=\"80\" y=\"140\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">[0,1]×[0,1] compact</text><text x=\"170\" y=\"75\" font-size=\"20\" fill=\"#c8922a\" text-anchor=\"middle\">×</text><rect x=\"190\" y=\"20\" width=\"100\" height=\"100\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3\" stroke-dasharray=\"6 4\"/><text x=\"240\" y=\"60\" font-size=\"26\" fill=\"#c8922a\" text-anchor=\"middle\">⋯</text><text x=\"240\" y=\"140\" font-size=\"11\" fill=\"#c8922a\" text-anchor=\"middle\">produs infinit, tot compact</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă fiecare sertar dintr-un dulap e ordonat și nu are cum să „scape” de sub control, adică e compact, atunci tot dulapul, chiar dacă are infinit de multe sertare, rămâne la fel de „sub control”</span>.",intuitiv_nota:"Andrey Tychonoff a demonstrat rezultatul în 1930, iar el s-a dovedit ulterior echivalent cu Axioma Alegerii. Stă la baza teoriei măsurii pe spații infinite și a unei bune părți din analiza funcțională.",exercitii:[{"q":"[0,1]×[0,1] (pătratul unitate) este compact?","pasi":["Fiecare factor, [0,1], este compact, închis și mărginit, prin Heine-Borel.","Prin teorema lui Tychonoff, produsul unui număr finit, sau infinit, de spații compacte este compact.","Deci [0,1]×[0,1] este compact."],"r":"✓ <strong>Da</strong>"},{"q":"De ce ℝ×ℝ (planul ℝ²) NU este compact?","pasi":["Factorul ℝ nu este mărginit, deci nu este compact, nu satisface Heine-Borel.","Tychonoff cere ca FIECARE factor din produs să fie compact - aici ipoteza eșuează deja pentru un singur factor.","Fără compacitatea fiecărui factor, produsul poate „scăpa” spre infinit - ℝ² nu e compact."],"r":"✓ <strong>Nu</strong> - factorul ℝ nu e compact"},{"q":"Spațiul {0,1}^ℕ, toate șirurile infinite de 0 și 1, este compact?","pasi":["{0,1} este o mulțime finită, deci automat compactă, orice mulțime finită e compactă.","{0,1}^ℕ este produsul infinit numărabil al acestei mulțimi compacte, cu topologia produs.","Prin Tychonoff, produsul infinit rămâne compact - un rezultat surprinzător, pentru că mulțimea are „infinit de multe dimensiuni”."],"r":"✓ <strong>Da</strong>, compact, deși infinit-dimensional"},{"q":"Adevărat sau fals: dacă un singur factor dintr-un produs nu e compact, atunci întregul produs nu e compact.","pasi":["Adevărat - Tychonoff este o echivalență, „dacă și numai dacă”, nu doar o implicație într-un sens.","Dacă măcar un factor Xα nu e compact, se poate construi o acoperire deschisă a produsului fără subacoperire finită, folosind acoperirea „vinovată” de pe acel factor.","Deci compactitatea produsului cere STRICT ca toți factorii să fie compacți."],"r":"✓ <strong>Adevărat</strong>"},{"q":"Spațiul {0,1}^ℕ se folosește ca model pentru un șir infinit de aruncări de monedă. De ce e util că e compact?","pasi":["Compacitatea garantează că orice șir de „evenimente parțiale”, aproximări finite ale rezultatelor, are un punct limită coerent în spațiul complet al rezultatelor infinite.","Aceasta stă la baza construcției riguroase a măsurilor de probabilitate pe spații de șiruri infinite.","Practic, permite matematicienilor să lucreze cu „infinit de multe aruncări de monedă” ca obiect matematic bine definit."],"r":"✓ Compacitatea susține <strong>construcția probabilității pe șiruri infinite</strong>"}]};
CONTINUT_TOPOLOGIE["teorema-lui-urysohn"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Într-un spațiu topologic normal X, pentru orice două mulțimi închise disjuncte A și B, există o funcție continuă f:X→[0,1] astfel încât f(A)={0} și f(B)={1}.</div>",formula_display:"X normal, A,B închise disjuncte → ∃f:X→[0,1] continuă, f(A)=0, f(B)=1",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><defs><linearGradient id=\"g1\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#1a6040\"/><stop offset=\"1\" stop-color=\"#c8922a\"/></linearGradient></defs><rect x=\"20\" y=\"30\" width=\"260\" height=\"90\" rx=\"8\" fill=\"url(#g1)\" fill-opacity=\"0.18\" stroke=\"#1a6040\" stroke-width=\"2\"/><circle cx=\"65\" cy=\"75\" r=\"30\" fill=\"#1a6040\" fill-opacity=\"0.5\" stroke=\"#1a6040\" stroke-width=\"2\"/><text x=\"65\" y=\"80\" font-size=\"13\" fill=\"#ffffff\" text-anchor=\"middle\">A→0</text><circle cx=\"235\" cy=\"75\" r=\"30\" fill=\"#c8922a\" fill-opacity=\"0.6\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"235\" y=\"80\" font-size=\"13\" fill=\"#ffffff\" text-anchor=\"middle\">B→1</text><text x=\"150\" y=\"140\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">tranziție continuă de la 0 la 1</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă ai două grupuri de jucării așezate separat pe covor, poți colora covorul într-un gradient de la alb la negru, astfel încât un grup să stea exact pe alb și celălalt exact pe negru, cu nuanțe line între ele</span>. Așa arată separarea printr-o funcție continuă.",intuitiv_nota:"Pavel Urysohn a publicat rezultatul în 1925. El devine piatra de temelie pentru teorema de metrizare a lui Urysohn și justifică folosirea funcțiilor continue ca instrumente de separare în topologia generală.",exercitii:[{"q":"Fie X=ℝ (spațiu metric, deci normal), A=(-∞,0], B=[1,∞). Găsiți o funcție continuă f:ℝ→[0,1] cu f(A)=0, f(B)=1.","pasi":["ℝ e metric, deci e normal, iar lema se aplică.","Construim f(x)=0 pentru x≤0, f(x)=x pentru 0≤x≤1 și f(x)=1 pentru x≥1.","f e continuă, fiind lipită din bucăți continue care coincid la capete."],"r":"✓ f(x)=min(max(x,0),1) - <strong>funcția „clamp”</strong>"},{"q":"De ce este esențială ipoteza de normalitate a spațiului X?","pasi":["Normalitatea garantează exact că mulțimile închise disjuncte pot fi separate prin vecinătăți deschise disjuncte.","Pe această separare se bazează construcția diadică din demonstrația lui Urysohn, cu mulțimi intermediare indexate de numere diadice.","Fără normalitate, o funcție de separare continuă poate să nu existe."],"r":"✓ Normalitatea e <strong>ipoteza minimală</strong> necesară"},{"q":"Orice spațiu metric este normal?","pasi":["Da: în spațiul metric (X,d), pentru A,B închise disjuncte funcția f(x)=d(x,A)/(d(x,A)+d(x,B)) este continuă.","f(A)=0 și f(B)=1, deci e chiar o funcție Urysohn explicită."],"r":"✓ <strong>Da</strong>, toate spațiile metrice sunt normale"},{"q":"Folosind f(x)=d(x,A)/(d(x,A)+d(x,B)) pentru A=[0,1], B=[3,4]⊂ℝ, calculați f(2).","pasi":["d(2,A)=1, distanța de la 2 la [0,1].","d(2,B)=1, distanța de la 2 la [3,4].","f(2)=1/(1+1)=1/2."],"r":"✓ f(2)=<strong>1/2</strong>"},{"q":"Ce relație are lema lui Urysohn cu teorema de metrizare a lui Urysohn?","pasi":["Teorema de metrizare cere ca spațiul să fie regulat, T1 și cu bază numărabilă.","Aplicând repetat lema lui Urysohn se construiește o scufundare a spațiului în cubul Hilbert [0,1]^ℕ.","Această scufundare arată că spațiul este metrizabil."],"r":"✓ Lema stă la baza <strong>demonstrației teoremei de metrizare</strong>"}]};
CONTINUT_TOPOLOGIE["teorema-lui-baire"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă (X,d) este un spațiu metric complet, atunci intersecția oricărei familii numărabile de mulțimi deschise și dense în X este densă în X. Echivalent, X nu poate fi scris ca reuniune numărabilă de mulțimi nicăieri dense (X e de categoria a II-a Baire).</div>",formula_display:"X metric complet, (Uₙ) deschise dense → ⋂ₙUₙ densă în X",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"260\" height=\"120\" rx=\"8\" fill=\"#1a604015\" stroke=\"#1a6040\" stroke-width=\"3\"/><circle cx=\"60\" cy=\"50\" r=\"18\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/><circle cx=\"120\" cy=\"90\" r=\"22\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/><circle cx=\"200\" cy=\"55\" r=\"16\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/><circle cx=\"240\" cy=\"105\" r=\"20\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/><circle cx=\"150\" cy=\"45\" r=\"14\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/><g fill=\"#1a6040\"><circle cx=\"40\" cy=\"30\" r=\"2.5\"/><circle cx=\"85\" cy=\"120\" r=\"2.5\"/><circle cx=\"160\" cy=\"115\" r=\"2.5\"/><circle cx=\"255\" cy=\"35\" r=\"2.5\"/><circle cx=\"110\" cy=\"35\" r=\"2.5\"/><circle cx=\"220\" cy=\"125\" r=\"2.5\"/></g><text x=\"150\" y=\"158\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">intersecția rămâne densă peste tot</text></svg>",intuitiv_text:"<span class=\"hl\">Un burete complet îmbibat cu apă nu poate fi „golit” prin doar numărate găurele mici - oricâte ai înțepa, tot mai rămâne apă peste tot, în orice colțișor</span>. La fel, un spațiu complet nu poate fi „epuizat” de numărat de multe mulțimi mici.",intuitiv_nota:"René-Louis Baire a publicat teorema în 1899, iar de atunci ea stă la baza unor rezultate fundamentale de analiză funcțională: teorema aplicației deschise, teorema graficului închis și principiul mărginirii uniforme al lui Banach și Steinhaus.",exercitii:[{"q":"ℚ (numerele raționale, cu metrica uzuală) satisface concluzia teoremei lui Baire?","pasi":["ℚ nu e complet, există șiruri Cauchy de raționale care converg la iraționale.","ℚ=⋃_{q∈ℚ}{q} este o reuniune numărabilă de mulțimi închise cu interior vid.","Deci ℚ este de categoria I în el însuși, iar teorema lui Baire nu i se aplică."],"r":"✓ <strong>Nu</strong> - ℚ nu e complet"},{"q":"Arătați că ℝ nu poate fi scris ca reuniune numărabilă de mulțimi închise cu interior vid.","pasi":["ℝ este spațiu metric complet.","Dacă ℝ=⋃ₙFₙ cu Fₙ închise cu interior vid, mulțimile Uₙ=ℝ\\Fₙ sunt deschise și dense.","Prin Baire, ⋂ₙUₙ e densă, deci nevidă, așa că există un x care nu aparține niciunui Fₙ - contradicție."],"r":"✓ <strong>Contradicție</strong> - ℝ e de categoria a II-a"},{"q":"[0,1] cu metrica uzuală este spațiu metric complet? Se aplică teorema lui Baire?","pasi":["[0,1] e închis în ℝ, deci complet ca spațiu metric.","Da, teorema lui Baire se aplică pe [0,1]."],"r":"✓ <strong>Da</strong>"},{"q":"Mulțimea numerelor iraționale ℝ\\ℚ este de categoria a II-a Baire în ea însăși?","pasi":["ℝ\\ℚ este Gδ în ℝ, o intersecție numărabilă de mulțimi deschise, deci e spațiu metrizabil complet cu o metrică echivalentă - un spațiu Polish.","Fiind complet, satisface teorema lui Baire, deci e de categoria a II-a în ea însăși."],"r":"✓ <strong>Da</strong>, categoria a II-a"},{"q":"De ce teorema lui Baire arată că un spațiu Banach infinit-dimensional nu poate avea o bază Hamel numărabilă?","pasi":["Dacă baza Hamel ar fi B={e₁,e₂,...}, atunci X=⋃ₙ span{e₁,...,eₙ}.","Fiecare subspațiu finit-dimensional este închis și are interior vid în X, care e infinit-dimensional.","Prin Baire, un spațiu complet nu poate fi o astfel de reuniune numărabilă de mulțimi rare - contradicție."],"r":"✓ <strong>Contradicție</strong> cu categoria Baire"}]};
CONTINUT_TOPOLOGIE["teorema-lui-arzela-ascoli"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie K un spațiu metric compact și F o familie de funcții continue f:K→ℝ. Familia F este relativ compactă în C(K) (orice șir din F are un subșir uniform convergent) dacă și numai dacă F este uniform mărginită și echicontinuă.</div>",formula_display:"F⊂C(K) relativ compactă ↔ F mărginită uniform + echicontinuă",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"260\" height=\"120\" rx=\"8\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><path d=\"M30 100 Q90 40 150 80 Q210 120 270 60\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\"/><path d=\"M30 90 Q90 50 150 85 Q210 110 270 70\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\" opacity=\"0.7\"/><path d=\"M30 110 Q90 60 150 75 Q210 105 270 55\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><text x=\"150\" y=\"155\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">familie mărginită + fără salturi bruște</text></svg>",intuitiv_text:"<span class=\"hl\">Un mănunchi de elastice întinse toate „la fel de lin”, fără sărituri bruște, și care nu ies dintr-o cutie - poți alege mereu câteva dintre ele care se apropie tot mai mult unele de altele</span>. Aceasta e echicontinuitatea plus mărginirea.",intuitiv_nota:"Rezultatul îi are ca autori pe Cesare Arzelà și Giulio Ascoli, spre sfârșitul secolului al XIX-lea, și rămâne un instrument esențial pentru existența soluțiilor ecuațiilor diferențiale (teorema lui Peano), pentru calculul variațional și pentru teoria operatorilor compacți.",exercitii:[{"q":"Familia fₙ(x)=sin(nx) pe [0,1] este echicontinuă?","pasi":["Derivata lui fₙ este n·cos(nx), care crește nemărginit odată cu n.","Pantele devin oricât de mari, deci nu există un δ uniform valabil pentru toate n.","Familia nu este echicontinuă."],"r":"✓ <strong>Nu</strong> - oscilațiile devin necontrolate"},{"q":"Familia fₙ(x)=xⁿ pe [0,1] este mărginită uniform? Este echicontinuă?","pasi":["|fₙ(x)|≤1 pentru orice x∈[0,1], deci familia e mărginită uniform.","Lângă x=1 însă, fₙ sare brusc de la valori mici la 1 pe măsură ce n crește (verificați în x=1-1/n), deci nu e echicontinuă."],"r":"✓ Mărginită, dar <strong>nu echicontinuă</strong>"},{"q":"Familia funcțiilor L-lipschitziene (aceeași constantă L) pe [0,1] este echicontinuă?","pasi":["|f(x)-f(y)|≤L|x-y| pentru toate funcțiile din familie.","Alegem δ=ε/L, valabil uniform pentru toate funcțiile.","Familia este echicontinuă."],"r":"✓ <strong>Da</strong>, condiția Lipschitz uniformă implică echicontinuitate"},{"q":"De ce se cere ca domeniul K să fie compact în enunț?","pasi":["Pe un domeniu necompact, de exemplu ℝ, o familie poate fi echicontinuă și mărginită punctual, dar poate „scăpa spre infinit” prin translatare.","Compacitatea lui K garantează controlul uniform necesar pentru extragerea subșirului convergent prin procedeul diagonal."],"r":"✓ Compacitatea lui K este <strong>esențială</strong>"},{"q":"Familia constantă fₙ(x)=1/n pe [0,1]. Are subșir uniform convergent?","pasi":["Este mărginită uniform (|fₙ|≤1) și echicontinuă, fiind funcții constante, așa că orice δ funcționează.","Arzelà-Ascoli garantează un subșir uniform convergent.","De fapt fₙ→0 uniform, fără să fie nevoie de subșir."],"r":"✓ <strong>Da</strong>, fₙ→0 uniform"}]};
CONTINUT_TOPOLOGIE["conexitate-prin-drumuri"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Un spațiu topologic X este conex prin drumuri dacă pentru orice două puncte x,y∈X există o funcție continuă γ:[0,1]→X (un drum) cu γ(0)=x și γ(1)=y. Orice spațiu conex prin drumuri este conex, dar reciproca nu este adevărată în general.</div>",formula_display:"∀x,y∈X ∃γ:[0,1]→X continuă, γ(0)=x, γ(1)=y",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M60 100 C50 60 100 40 150 60 C200 40 250 60 240 100 C250 130 190 150 150 130 C100 150 50 140 60 100 Z\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"3\"/><circle cx=\"90\" cy=\"90\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"210\" cy=\"90\" r=\"6\" fill=\"#c8922a\"/><path d=\"M90 90 Q150 130 210 90\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/><text x=\"150\" y=\"20\" font-size=\"12\" fill=\"#1a6040\" text-anchor=\"middle\">drum continuu între orice două puncte</text></svg>",intuitiv_text:"<span class=\"hl\">Poți merge cu creionul pe hârtie de la orice punct la oricare altul fără să ridici creionul, rămânând tot timpul în interiorul desenului</span>. Dacă desenul are două bucăți separate, nu poți trece de la una la alta fără să sari.",intuitiv_nota:"Concept clasic al topologiei generale, folosit intens în topologia algebrică (grupul fundamental se definește pe componentele conexe prin drumuri). Contraexemplul clasic pentru „conex dar nu prin drumuri” este curba sinusului topologului.",exercitii:[{"q":"Discul unitate D={(x,y):x²+y²≤1} este conex prin drumuri?","pasi":["Pentru orice două puncte P,Q∈D, segmentul de dreaptă [P,Q] rămâne în D, deoarece D este convex.","Segmentul este un drum continuu, deci D este conex prin drumuri."],"r":"✓ <strong>Da</strong>, D e convex deci conex prin drumuri"},{"q":"Mulțimea X=[0,1]∪[2,3]⊂ℝ este conexă prin drumuri?","pasi":["Luăm x=0,5∈[0,1] și y=2,5∈[2,3].","Orice drum continuu γ cu γ(0)=0,5 și γ(1)=2,5 ar trebui, prin teorema valorii intermediare, să treacă prin punctul 1,5∉X.","Un astfel de drum nu poate exista în X."],"r":"✓ <strong>Nu</strong> - cele două intervale sunt componente separate"},{"q":"Cercul S¹={(x,y):x²+y²=1} este conex prin drumuri?","pasi":["Pentru orice două puncte de pe cerc, arcul dintre ele, parametrizat prin unghi, este un drum continuu.","S¹ este conex prin drumuri."],"r":"✓ <strong>Da</strong>"},{"q":"Conexitatea prin drumuri implică conexitatea topologică?","pasi":["Dacă X ar fi neconex, X=A∪B cu A,B deschise, disjuncte, nevide.","Imaginea unui drum γ:[0,1]→X este conexă, fiind imaginea continuă a intervalului [0,1], care e conex.","Un drum ce unește un punct din A cu unul din B ar avea deci imaginea neconexă în raport cu A,B - contradicție."],"r":"✓ <strong>Da</strong>, implicația e adevărată (reciproca nu, în general)"},{"q":"Curba sinusului topologului: graficul lui sin(1/x) pentru x∈(0,1], reunit cu segmentul {0}×[-1,1]. Este conexă prin drumuri?","pasi":["Mulțimea este conexă topologic, nu poate fi separată în două deschise disjuncte.","Dar nu există drum continuu de la un punct al graficului la un punct al segmentului {0}×[-1,1], pentru că oscilațiile infinite ale sin(1/x) lângă x=0 ar face orice astfel de drum discontinuu.","Mulțimea e conexă, dar nu conexă prin drumuri."],"r":"✓ <strong>Nu</strong> - conexă, dar nu conexă prin drumuri"}]};
CONTINUT_TOPOLOGIE["teorema-lui-stone-weierstrass"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie X un spațiu compact Hausdorff și A o subalgebră de funcții continue din C(X,ℝ) care conține funcțiile constante și separă punctele lui X (pentru orice x≠y există f∈A cu f(x)≠f(y)). Atunci A este densă în C(X,ℝ) în raport cu norma sup.</div>",formula_display:"A subalgebră, separă puncte, conține constantele → A̅ = C(X)",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M20 90 C60 30 100 140 140 70 C180 10 220 130 280 60\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"3\"/><path d=\"M20 90 C60 50 100 120 140 75 C180 30 220 115 280 65\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><text x=\"150\" y=\"20\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">funcție continuă (verde) și aproximare polinomială (auriu)</text><text x=\"150\" y=\"155\" font-size=\"11\" fill=\"#c8922a\" text-anchor=\"middle\">aproximarea se apropie oricât de mult</text></svg>",intuitiv_text:"<span class=\"hl\">Cu suficient de multe piese Lego (polinoame), poți construi o formă din ce în ce mai apropiată de orice curbă continuă, oricât de complicată</span> - atâta timp cât piesele pot distinge orice două puncte diferite.",intuitiv_nota:"Marshall Stone a demonstrat forma generală a teoremei în 1937; polinoamele pe [a,b] și polinoamele trigonometrice pe cerc rămân cazurile particulare cele mai celebre. Rezultatul fundamentează teoria aproximării și analiza Fourier.",exercitii:[{"q":"Mulțimea polinoamelor P pe [0,1] este densă în C([0,1])? Justificați cu Stone-Weierstrass.","pasi":["P este subalgebră, închisă la sumă și la produs.","Conține și funcțiile constante.","Separă punctele: pentru x≠y, funcția f(t)=t satisface f(x)≠f(y).","Toate ipotezele fiind verificate, P este densă în C([0,1])."],"r":"✓ <strong>Da</strong> - regăsim teorema clasică Weierstrass"},{"q":"Polinoamele pare (doar puteri pare de x) pe [-1,1] sunt dense în C([-1,1])?","pasi":["Algebra generată de x² este o subalgebră care conține constantele.","Dar nu separă punctele -1 și 1: orice polinom par satisface f(-1)=f(1).","Ipoteza de separare eșuează, deci algebra nu e densă - nu poate aproxima funcții impare, de exemplu f(x)=x."],"r":"✓ <strong>Nu</strong> - nu separă punctele -1 și 1"},{"q":"Polinoamele trigonometrice (combinații de sin(nx), cos(nx)) sunt dense în C(S¹) (funcții continue periodice)?","pasi":["Formează o subalgebră: prin identitățile trigonometrice, produsele rămân în spațiul generat.","Conțin constanta 1=cos(0·x).","Separă punctele pe cerc, deoarece sin și cos disting unghiuri distincte.","Prin Stone-Weierstrass, sunt dense în C(S¹)."],"r":"✓ <strong>Da</strong> - bază pentru seriile Fourier"},{"q":"De ce este necesară ipoteza ca X să fie compact?","pasi":["Pe un spațiu necompact, funcțiile continue pot fi nemărginite, iar norma sup nu mai controlează comportamentul global.","Compacitatea garantează că orice f∈C(X) e mărginită și că aproximarea uniformă are sens pe tot spațiul."],"r":"✓ Compacitatea este <strong>esențială</strong> pentru enunțul standard"},{"q":"Algebra A={f∈C([0,1]): f(0)=0} este densă în C([0,1])?","pasi":["A este subalgebră, dar nu conține funcțiile constante nenule, deoarece constanta c≠0 nu satisface f(0)=0.","Ipoteza „conține constantele” nu este îndeplinită.","Orice g din aderența lui A satisface g(0)=0, deci aderența nu poate fi tot C([0,1]) - funcția constantă 1 nu poate fi aproximată."],"r":"✓ <strong>Nu</strong> - nu conține constantele"}]};
CONTINUT_TOPOLOGIE["compactitate-secventiala"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Un spațiu topologic X este secvențial compact dacă orice șir (xₙ) de puncte din X are un subșir convergent către un punct din X. Într-un spațiu metric, compacitatea secvențială este echivalentă cu compacitatea topologică.</div>",formula_display:"∀(xₙ)⊂X ∃subșir (x_{n_k}) convergent în X",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"260\" height=\"120\" rx=\"10\" fill=\"none\" stroke=\"#1a6040\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><circle cx=\"50\" cy=\"40\" r=\"3\" fill=\"#1a6040\"/><circle cx=\"90\" cy=\"120\" r=\"3\" fill=\"#1a6040\"/><circle cx=\"200\" cy=\"35\" r=\"3\" fill=\"#1a6040\"/><circle cx=\"60\" cy=\"90\" r=\"3\" fill=\"#1a6040\"/><circle cx=\"230\" cy=\"110\" r=\"3\" fill=\"#1a6040\"/><circle cx=\"170\" cy=\"95\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"180\" cy=\"85\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"187\" cy=\"80\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"191\" cy=\"77\" r=\"3\" fill=\"#c8922a\"/><circle cx=\"194\" cy=\"75\" r=\"5\" fill=\"#c8922a\"/><text x=\"194\" y=\"60\" font-size=\"10\" fill=\"#c8922a\" text-anchor=\"middle\">subșir care se adună</text></svg>",intuitiv_text:"<span class=\"hl\">Un roi de albine care nu poate zbura oriunde la nesfârșit - oricât de haotic ar zbura roiul, mereu se poate găsi un grup din ele care se adună tot mai aproape într-un colț al grădinii</span>.",intuitiv_nota:"Concept clasic de topologie generală. În spații metrice coincide cu compacitatea, prin teorema Bolzano-Weierstrass generalizată, dar în spații topologice generale cele două noțiuni pot diferi.",exercitii:[{"q":"Șirul xₙ=(-1)ⁿ în [-1,1]. Are subșir convergent?","pasi":["Subșirul termenilor pari x_{2k}=1 este constant egal cu 1.","Un subșir constant converge la 1."],"r":"✓ <strong>Da</strong>, subșirul termenilor pari converge la 1"},{"q":"[0,1] este secvențial compact?","pasi":["[0,1] este compact prin Heine-Borel și e totodată spațiu metric.","Compact și metric implică secvențial compact.","Orice șir din [0,1] are un subșir convergent, conform Bolzano-Weierstrass."],"r":"✓ <strong>Da</strong>"},{"q":"Șirul xₙ=n în ℝ. Are subșir convergent în ℝ?","pasi":["Orice subșir al lui xₙ=n tinde tot la +∞.","Niciun subșir nu converge la un număr real, deci ℝ nu este secvențial compact."],"r":"✓ <strong>Nu</strong> - ℝ nu e secvențial compact"},{"q":"Șirul de funcții fₙ(x)=xⁿ în C([0,1]) cu norma sup - are subșir uniform convergent?","pasi":["fₙ converge punctual la funcția discontinuă egală cu 0 pe [0,1) și cu 1 în x=1, dar nu uniform.","Orice subșir converge punctual la aceeași limită discontinuă, deci niciun subșir nu poate converge uniform la o funcție continuă."],"r":"✓ <strong>Nu</strong> - ilustrează diferența dintre convergența punctuală și cea uniformă"},{"q":"În spații metrice, de ce sunt echivalente compacitatea și compacitatea secvențială?","pasi":["Compact ⇒ secvențial compact: dacă un șir n-ar avea subșir convergent, fiecare punct ar avea o vecinătate ce conține doar un număr finit de termeni, ceea ce ar da o acoperire deschisă fără subacoperire finită.","Secvențial compact ⇒ compact: folosind totala mărginire și completitudinea, echivalente cu compacitatea secvențială în spații metrice, se construiește o subacoperire finită din orice acoperire deschisă."],"r":"✓ <strong>Echivalente</strong> datorită structurii metrice"}]};
CONTINUT_TOPOLOGIE["teorema-lui-tietze"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie X un spațiu topologic normal, A⊂X o submulțime închisă și f:A→ℝ o funcție continuă și mărginită. Atunci există o extensie continuă F:X→ℝ cu F restricționată la A egală cu f, iar F poate fi aleasă cu aceleași margini ca f.</div>",formula_display:"X normal, A închisă, f:A→ℝ continuă mărginită → ∃F:X→ℝ continuă, F|_A=f",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"260\" height=\"120\" rx=\"8\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><ellipse cx=\"90\" cy=\"80\" rx=\"45\" ry=\"30\" fill=\"#1a604022\" stroke=\"#1a6040\" stroke-width=\"3\"/><text x=\"90\" y=\"85\" font-size=\"11\" fill=\"#1a6040\" text-anchor=\"middle\">A (f definită)</text><path d=\"M135 80 C170 60 210 100 260 70\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\" stroke-dasharray=\"5 3\"/><text x=\"220\" y=\"130\" font-size=\"11\" fill=\"#c8922a\" text-anchor=\"middle\">extensie continuă F pe tot X</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă ai desenat ceva pe o insulă (o bucată închisă din hartă), poți continua desenul pe toată harta din jur, fără rupturi, păstrând aceleași culori-limită</span>. Este generalizarea lemei lui Urysohn.",intuitiv_nota:"Heinrich Tietze a demonstrat rezultatul în 1915, printr-o succesiune de aplicări ale lemei lui Urysohn care construiesc extensia prin aproximări succesive. Teorema rămâne esențială în topologia algebrică și în teoria fibrărilor.",exercitii:[{"q":"f:{0,1}→ℝ, f(0)=0, f(1)=1, definită pe submulțimea închisă A={0,1}⊂X=[0,2]. Găsiți o extensie continuă F:[0,2]→ℝ.","pasi":["A={0,1} este închisă în X=[0,2].","O extensie posibilă: F(x)=x pentru x∈[0,1] și F(x)=1 pentru x∈[1,2].","F este continuă, iar restricția ei la A coincide cu f."],"r":"✓ F(x)=min(x,1) - <strong>una din extensiile posibile</strong> (nu e unică)"},{"q":"De ce trebuie ca A să fie închisă în X?","pasi":["Dacă A nu ar fi închisă, ar exista puncte de acumulare ale lui A în afara lui A, unde valoarea extensiei ar deveni ambiguă.","Fără închiderea lui A, continuitatea extensiei F pe frontiera ei nu ar mai putea fi garantată."],"r":"✓ Închiderea lui A este <strong>ipoteză esențială</strong>"},{"q":"f:A→ℝ este mărginită de M (|f|≤M) pe A închisă. Extensia F poate fi aleasă cu |F|≤M pe tot X?","pasi":["Da, enunțul complet al teoremei lui Tietze garantează că extensia poate fi aleasă păstrând marginile lui f.","Construcția standard, printr-o serie de funcții Urysohn cu factor 2/3, păstrează explicit această margine."],"r":"✓ <strong>Da</strong>, extensia păstrează marginile"},{"q":"Cum se leagă teorema lui Tietze de lema lui Urysohn?","pasi":["Lema lui Urysohn, care dă funcții cu valori între 0 și 1 pe mulțimi închise disjuncte, este instrumentul folosit la construcția extensiei generale a lui Tietze.","Demonstrația standard a lui Tietze aplică succesiv lema lui Urysohn în aproximări cu factor 1/3."],"r":"✓ Lema lui Urysohn este <strong>ingredientul de bază</strong> al demonstrației"},{"q":"f:A→ℝ continuă dar nemărginită pe A închisă din X normal. Se poate extinde continuu?","pasi":["Da, teorema lui Tietze se extinde și la funcții nemărginite, folosind un homeomorfism între ℝ și intervalul (-1,1) pentru a reduce la cazul mărginit.","Se extinde funcția mărginită obținută, apoi se verifică că extensia nu atinge valorile ±1, ceea ce permite revenirea la ℝ."],"r":"✓ <strong>Da</strong>, teorema se extinde și la cazul nemărginit"}]};
